+// TestOrgIsolation_TwoOrgs exercises the workspace-scoping guarantee at the HTTP layer:
+//   - client_member of org A (AccessibleWorkspaceIDs = [wsAID]) sees only wsA on
+//     GET /api/workspaces and gets 404 on GET /api/workspaces/{wsBID}.
+//   - platform_admin (AccessibleWorkspaceIDs = [wsAID, wsBID]) sees both workspaces.
+func TestOrgIsolation_TwoOrgs(t *testing.T) {
+	const (
+		wsAID = "aaaaaaaa-1111-1111-1111-111111111111"
+		wsBID = "cccccccc-3333-3333-3333-333333333333"
+	)
+
+	wsA := testhelpers.NewWorkspace(wsAID, "Workspace A", "ws-a")
+	wsB := testhelpers.NewWorkspace(wsBID, "Workspace B", "ws-b")
+
+	db := &testhelpers.FakeDB{
+		Workspaces: []database.Workspace{wsA, wsB},
+	}
+	adp := &testhelpers.FakeAdapter{}
+
+	// client_member of org A can only see wsA.
+	clientA := &authmw.AuthCtx{
+		UserID:                 "user-client-a",
+		OrganizationID:         "org-a",
+		AccessibleWorkspaceIDs: []string{wsAID},
+	}
+	srvClientA := newServerWithAuth(db, adp, clientA)
+	defer srvClientA.Close()
+
+	// platform_admin has access to both workspaces.
+	admin := &authmw.AuthCtx{
+		UserID:                 "user-admin",
+		OrganizationID:         "org-kitelabs",
+		AccessibleWorkspaceIDs: []string{wsAID, wsBID},
+	}
+	srvAdmin := newServerWithAuth(db, adp, admin)
+	defer srvAdmin.Close()
+
+	t.Run("client_member sees only org A workspace", func(t *testing.T) {
+		resp := get(t, srvClientA, "/api/workspaces")
+		defer func() { _ = resp.Body.Close() }()
+		if resp.StatusCode != http.StatusOK {
+			t.Fatalf("expected 200, got %d", resp.StatusCode)
+		}
+		workspaces := decodeAPIData[[]domain.WorkspaceSummary](t, resp)
+		if len(workspaces) != 1 {
+			t.Fatalf("client_member of org A: expected 1 workspace, got %d", len(workspaces))
+		}
+		if workspaces[0].ID != wsAID {
+			t.Errorf("expected workspace ID %s, got %s", wsAID, workspaces[0].ID)
+		}
+	})
+
+	t.Run("client_member gets 404 for org B workspace", func(t *testing.T) {
+		resp := get(t, srvClientA, "/api/workspaces/"+wsBID)
+		defer func() { _ = resp.Body.Close() }()
+		if resp.StatusCode != http.StatusNotFound {
+			t.Fatalf("client_member accessing org B workspace: expected 404, got %d", resp.StatusCode)
+		}
+		apiErr := decodeAPIError(t, resp)
+		if apiErr.Code != domain.ErrDatabaseNotFound {
+			t.Errorf("expected ErrDatabaseNotFound, got %s", apiErr.Code)
+		}
+	})
+
+	t.Run("platform_admin sees both workspaces", func(t *testing.T) {
+		resp := get(t, srvAdmin, "/api/workspaces")
+		defer func() { _ = resp.Body.Close() }()
+		if resp.StatusCode != http.StatusOK {
+			t.Fatalf("expected 200, got %d", resp.StatusCode)
+		}
+		workspaces := decodeAPIData[[]domain.WorkspaceSummary](t, resp)
+		if len(workspaces) != 2 {
+			t.Fatalf("platform_admin: expected 2 workspaces, got %d", len(workspaces))
+		}
+		seen := make(map[string]bool, 2)
+		for _, ws := range workspaces {
+			seen[ws.ID] = true
+		}
+		if !seen[wsAID] {
+			t.Errorf("platform_admin: expected to see workspace %s", wsAID)
+		}
+		if !seen[wsBID] {
+			t.Errorf("platform_admin: expected to see workspace %s", wsBID)
+		}
+	})
+}
