package database

import (
	"context"
	"errors"
	"fmt"
	"strings"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"

	"github.com/tiendv89/workflow-backend/internal/authmw"
)

// ErrNotFound is returned when a queried row does not exist.
var ErrNotFound = errors.New("not found")

// ScopedWorkspaceIDs extracts the caller's accessible workspace UUIDs from the auth
// context and returns them for use in query WHERE clauses.
// Returns (nil, false) when no auth context is present (unauthenticated path).
// Returns ([]pgtype.UUID{}, true) when the user has zero accessible workspaces.
func ScopedWorkspaceIDs(ctx context.Context) ([]pgtype.UUID, bool) {
	ac, ok := authmw.FromContext(ctx)
	if !ok {
		return nil, false
	}
	uids := make([]pgtype.UUID, 0, len(ac.AccessibleWorkspaceIDs))
	for _, idStr := range ac.AccessibleWorkspaceIDs {
		var uid pgtype.UUID
		if uid.Scan(idStr) == nil {
			uids = append(uids, uid)
		}
	}
	return uids, true
}

// Reader executes read-only SQL queries against the shared PostgreSQL schema.
// All UUID parameters are accepted as hex strings and parsed internally.
type Reader struct {
	db *Pool
}

// FeatureSearchFilters contains optional filters and result controls for feature search.
type FeatureSearchFilters struct {
	Title  string
	Status string
	Sort   string
	Page   int
	Limit  int
}

// TaskSearchFilters contains optional filters and result controls for task search.
type TaskSearchFilters struct {
	TaskID string
	Title  string
	Status string
	Repo   string
	Sort   string
	Page   int
	Limit  int
}

// NewReader creates a new Reader.
func NewReader(db *Pool) *Reader {
	return &Reader{db: db}
}

// ListWorkspaces returns workspaces visible to the caller ordered by updated_at desc.
// When an auth context is present the result is filtered to the caller's accessible
// workspace IDs; a user with zero accessible workspaces gets an empty list.
func (r *Reader) ListWorkspaces(ctx context.Context) ([]Workspace, error) {
	accessible, hasAuth := ScopedWorkspaceIDs(ctx)
	if hasAuth && len(accessible) == 0 {
		return []Workspace{}, nil
	}

	var (
		q    string
		args []interface{}
	)
	if hasAuth {
		q = `
		SELECT id, organization_id, slug, name, management_repo_id, branch_pattern, created_at, updated_at
		FROM workspaces
		WHERE id = ANY($1)
		ORDER BY updated_at DESC`
		args = []interface{}{accessible}
	} else {
		q = `
		SELECT id, organization_id, slug, name, management_repo_id, branch_pattern, created_at, updated_at
		FROM workspaces
		ORDER BY updated_at DESC`
	}

	rows, err := r.db.Query(ctx, q, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []Workspace
	for rows.Next() {
		var w Workspace
		if err := rows.Scan(&w.ID, &w.OrganizationID, &w.Slug, &w.Name, &w.ManagementRepoID, &w.BranchPattern, &w.CreatedAt, &w.UpdatedAt); err != nil {
			return nil, err
		}
		out = append(out, w)
	}
	return out, rows.Err()
}

