package database_test

import (
	"context"
	"testing"

	"github.com/tiendv89/workflow-backend/internal/authmw"
	"github.com/tiendv89/workflow-backend/internal/database"
)

func TestScopedWorkspaceIDs_NoAuthContext(t *testing.T) {
	ids, ok := database.ScopedWorkspaceIDs(context.Background())
	if ok {
		t.Error("expected ok=false when no auth context is present")
	}
	if ids != nil {
		t.Errorf("expected nil ids when no auth context is present, got %v", ids)
	}
}

func TestScopedWorkspaceIDs_EmptyWorkspaceList(t *testing.T) {
	ctx := authmw.SetAuthCtx(context.Background(), &authmw.AuthCtx{
		UserID:                 "u1",
		OrganizationID:         "o1",
		AccessibleWorkspaceIDs: []string{},
	})

	ids, ok := database.ScopedWorkspaceIDs(ctx)
	if !ok {
		t.Error("expected ok=true when auth context is present")
	}
	if len(ids) != 0 {
		t.Errorf("expected empty ids for no accessible workspaces, got %v", ids)
	}
}

func TestScopedWorkspaceIDs_ValidUUIDs(t *testing.T) {
	wsID1 := "11111111-1111-1111-1111-111111111111"
	wsID2 := "22222222-2222-2222-2222-222222222222"

	ctx := authmw.SetAuthCtx(context.Background(), &authmw.AuthCtx{
		UserID:                 "u1",
		OrganizationID:         "o1",
		AccessibleWorkspaceIDs: []string{wsID1, wsID2},
	})

	ids, ok := database.ScopedWorkspaceIDs(ctx)
	if !ok {
		t.Error("expected ok=true when auth context is present")
	}
	if len(ids) != 2 {
		t.Fatalf("expected 2 UUIDs, got %d", len(ids))
	}
	// Verify the UUIDs are valid (non-zero)
	for i, uid := range ids {
		if !uid.Valid {
			t.Errorf("UUID at index %d is not valid", i)
		}
	}
}

func TestScopedWorkspaceIDs_InvalidUUIDsSkipped(t *testing.T) {
	wsID1 := "11111111-1111-1111-1111-111111111111"

	ctx := authmw.SetAuthCtx(context.Background(), &authmw.AuthCtx{
		UserID:                 "u1",
		AccessibleWorkspaceIDs: []string{wsID1, "not-a-uuid", ""},
	})

	ids, ok := database.ScopedWorkspaceIDs(ctx)
	if !ok {
		t.Error("expected ok=true when auth context is present")
	}
	if len(ids) != 1 {
		t.Errorf("expected 1 valid UUID (invalid ones skipped), got %d", len(ids))
	}
}

